    async def form_company(
        self,
        id: str,
        *,
        business_name: str,
        business_type: str,
        formation_state: FormCompanyAccountsRequestFormationState,
        founders: typing.Sequence[FormCompanyAccountsRequestFoundersItem],
        industry_group: str,
        industry_type: str,
        business_address: typing.Optional[FormCompanyAccountsRequestBusinessAddress] = OMIT,
        business_phone: typing.Optional[str] = OMIT,
        business_website: typing.Optional[str] = OMIT,
        entity_suffix: typing.Optional[FormCompanyAccountsRequestEntitySuffix] = OMIT,
        entity_type: typing.Optional[FormCompanyAccountsRequestEntityType] = OMIT,
        expedite_ein: typing.Optional[bool] = OMIT,
        share_structure: typing.Optional[FormCompanyAccountsRequestShareStructure] = OMIT,
        use_registered_agent: typing.Optional[bool] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> FormCompanyAccountsResponse:
        """
        Starts an LLC or C-Corp formation for a business account. Defaults to an LLC; set `entity_type` to `c_corp` to form a C-Corp, which additionally requires `share_structure` and officer `roles` on every founder. On submission, the application is validated and the response returns a hosted checkout URL. Once paid, the filing is submitted. Track progress through the account's [`company_formation`](/api-reference/beta/accounts/retrieve-account) field on Retrieve Account.

        Parameters
        ----------
        id : str
            Account ID, prefixed `biz_`.

        business_name : str
            Legal name for the new company.

        business_type : str
            High-level business category, from the Whop business taxonomy. Valid values are listed on [business types and industries glossary](/api-reference/beta/accounts/account#business-types-and-industries-glossary).

        formation_state : FormCompanyAccountsRequestFormationState
            Two-letter code of the US state (or `DC`) to form the company in. We recommend `WY` because Wyoming formations are completed the same day.

        founders : typing.Sequence[FormCompanyAccountsRequestFoundersItem]
            The company's founders. Exactly one must be marked `is_primary` — the responsible party for the filing.

        industry_group : str
            Industry group, from the Whop business taxonomy. Valid values are listed on [business types and industries glossary](/api-reference/beta/accounts/account#business-types-and-industries-glossary).

        industry_type : str
            Specific industry vertical, from the Whop business taxonomy. Valid values are listed on [business types and industries glossary](/api-reference/beta/accounts/account#business-types-and-industries-glossary).

        business_address : typing.Optional[FormCompanyAccountsRequestBusinessAddress]
            Company mailing address. Required unless `use_registered_agent` is `true`.

        business_phone : typing.Optional[str]
            Business phone number in E.164 format, for example `+12125550100`. Required unless `use_registered_agent` is `true`.

        business_website : typing.Optional[str]
            Company website URL.

        entity_suffix : typing.Optional[FormCompanyAccountsRequestEntitySuffix]
            Legal entity ending appended to `business_name`. LLC formations accept `LLC`, `L.L.C`, `L.L.C.` or `Limited Liability Company` and default to `LLC`; C-Corp formations accept `Inc`, `Inc.`, `Incorporated`, `Corp.`, `Corporation`, `C Corp`, `C Corporation`, `CCorp` or `Company` and default to `Inc.`. Unrecognized values fall back to the default for the entity type.

        entity_type : typing.Optional[FormCompanyAccountsRequestEntityType]
            Legal entity type to form. Defaults to `llc`.

        expedite_ein : typing.Optional[bool]
            Request expedited EIN processing for an additional fee. Available only when no founder supplies an SSN.

        share_structure : typing.Optional[FormCompanyAccountsRequestShareStructure]
            Authorized share structure. Required when `entity_type` is `c_corp`; ignored for LLCs.

        use_registered_agent : typing.Optional[bool]
            Use the registered agent's address as the company address instead of `business_address`.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        FormCompanyAccountsResponse
            application accepted and checkout created

        Examples
        --------
        import asyncio

        from whop_sdk import AsyncWhop
        from whop_sdk.accounts import (
            FormCompanyAccountsRequestBusinessAddress,
            FormCompanyAccountsRequestFoundersItem,
            FormCompanyAccountsRequestFoundersItemAddress,
            FormCompanyAccountsRequestShareStructure,
        )

        client = AsyncWhop(
            "2026-09-02-2",
            idempotency_key="YOUR_IDEMPOTENCY_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.accounts.form_company(
                id="id",
                business_address=FormCompanyAccountsRequestBusinessAddress(
                    city="Austin",
                    country="US",
                    line1="4180 Burnet Rd",
                    line2="Suite 2",
                    postal_code="78756",
                    state="TX",
                ),
                business_name="Shine Time Auto Detailing",
                business_phone="+15125550142",
                business_type="brick_and_mortar",
                business_website="https://shinetime.example",
                entity_suffix="LLC",
                entity_type="llc",
                expedite_ein=True,
                formation_state="WY",
                founders=[
                    FormCompanyAccountsRequestFoundersItem(
                        address=FormCompanyAccountsRequestFoundersItemAddress(
                            city="Austin",
                            country="US",
                            line1="907 Ridgemont Dr",
                            line2="Apt 4",
                            postal_code="78704",
                            state="TX",
                        ),
                        date_of_birth="1988-03-14",
                        email="marcus@shinetime.example",
                        first_name="Marcus",
                        is_primary=True,
                        last_name="Webb",
                        ownership_percentage=100.0,
                        phone="+15125550142",
                        roles=["president"],
                        ssn="123-45-6789",
                    )
                ],
                industry_group="automotive",
                industry_type="car_wash",
                share_structure=FormCompanyAccountsRequestShareStructure(
                    number_of_shares=123,
                    value=123.0,
                ),
                use_registered_agent=True,
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.form_company(
            id,
            business_name=business_name,
            business_type=business_type,
            formation_state=formation_state,
            founders=founders,
            industry_group=industry_group,
            industry_type=industry_type,
            business_address=business_address,
            business_phone=business_phone,
            business_website=business_website,
            entity_suffix=entity_suffix,
            entity_type=entity_type,
            expedite_ein=expedite_ein,
            share_structure=share_structure,
            use_registered_agent=use_registered_agent,
            request_options=request_options,
        )
        return _response.data

    async def suspend(self, id: str, *, request_options: typing.Optional[RequestOptions] = None) -> Account:
        """
        Suspends a connected account directly owned by the authenticated platform account. This cannot suspend the platform account itself or an account owned by another platform.

        Parameters
        ----------
        id : str
            Connected account ID, prefixed `biz_`.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Account
            Connected account suspended.

        Examples
        --------
        import asyncio

        from whop_sdk import AsyncWhop

        client = AsyncWhop(
            "2026-09-02-2",
            idempotency_key="YOUR_IDEMPOTENCY_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.accounts.suspend(
                id="id",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.suspend(id, request_options=request_options)
        return _response.data

    async def transfer_ownership(
        self,
        id: str,
        *,
        identifier: str,
        as_partner: typing.Optional[bool] = OMIT,
        message: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> TransferOwnershipAccountsResponse:
        """
        Transfers ownership of the account to another user, identified by user ID or email address. If the recipient already holds the owner role, ownership moves immediately; otherwise they get an invite and ownership moves when they accept.

        Parameters
        ----------
        id : str
            Account ID, prefixed `biz_`.

        identifier : str
            The user to transfer ownership to: a user ID (`user_*`) or an email address. An email address with no Whop account yet is sent an invite to create one.

        as_partner : typing.Optional[bool]
            If true, the current owner is credited as the account's Whop partner, earning partner commission on its sales. Requires the current owner to already be an enrolled Whop partner. Skipped if the account already has an active partner.

        message : typing.Optional[str]
            A note from the partner, shown as a quote in the invite email and signed with their name. Requires `as_partner`; sending it on an ordinary transfer is a 400. Omit it and the email sends without a note.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        TransferOwnershipAccountsResponse
            Ownership transferred.

        Examples
        --------
        import asyncio

        from whop_sdk import AsyncWhop

        client = AsyncWhop(
            "2026-09-02-2",
            idempotency_key="YOUR_IDEMPOTENCY_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.accounts.transfer_ownership(
                id="id",
                identifier="marcus@shinetime.example",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.transfer_ownership(
            id, identifier=identifier, as_partner=as_partner, message=message, request_options=request_options
        )
        return _response.data

